CREATE TABLE profissionais (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, estudio_id BIGINT NOT NULL REFERENCES estudios(id), nome VARCHAR(100) NOT NULL, ativo BOOLEAN NOT NULL DEFAULT TRUE, version BIGINT NOT NULL DEFAULT 0, configuracoes BIGINT NOT NULL DEFAULT 0, UNIQUE(id,estudio_id));
CREATE TABLE horarios_trabalho (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, profissional_id BIGINT NOT NULL REFERENCES profissionais(id), dia_semana INTEGER NOT NULL CHECK (dia_semana BETWEEN 1 AND 7), inicio TIME(6) NOT NULL, fim TIME(6) NOT NULL, CHECK(fim>inicio));
CREATE TABLE bloqueios_agenda (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, profissional_id BIGINT NOT NULL REFERENCES profissionais(id), inicio TIMESTAMP(6) NOT NULL, fim TIMESTAMP(6) NOT NULL, motivo VARCHAR(255), CHECK(fim>inicio));
CREATE INDEX idx_profissionais_estudio ON profissionais(estudio_id);
CREATE INDEX idx_horarios_profissional ON horarios_trabalho(profissional_id,dia_semana);
CREATE INDEX idx_bloqueios_profissional ON bloqueios_agenda(profissional_id,inicio,fim);
