ALTER TABLE marcacoes ADD COLUMN profissional_id BIGINT REFERENCES profissionais(id);
UPDATE marcacoes SET profissional_id=(SELECT MIN(p.id) FROM profissionais p WHERE p.estudio_id=marcacoes.estudio_id);
ALTER TABLE marcacoes ALTER COLUMN profissional_id SET NOT NULL;
ALTER TABLE marcacoes ADD CONSTRAINT fk_marcacao_profissional_estudio FOREIGN KEY(profissional_id,estudio_id) REFERENCES profissionais(id,estudio_id);
CREATE INDEX idx_marcacoes_profissional_data ON marcacoes(profissional_id,data);
